    'Welche Papierform trägt die meisten Münzen?': 'Which paper shape holds the most coins?',
    'Welche Regel gilt im Reich der Spinnenkönigin?':
      "What rule applies in the Spider Queen's realm?",
    'Welche Spur verrät, was wirklich passiert ist?': 'Which clue reveals what really happened?',
    'Welche Sterne und Planeten hast du in deiner Galaxie gesehen?':
      'Which stars and planets did you see in your galaxy?',
    'Welchen Monsternamen bekommt deine Figur?': 'What monster name will you give your character?',
    'Welcher Fluch steht auf der geheimen Botschaft?':
      'What curse is written on the secret message?',
    'Welcher Trank im Regal darf niemals geöffnet werden?':
      'Which potion on the shelf must never be opened?',
    'Welches Bild erzählt die stärkste Geschichte und warum?':
      'Which picture tells the most powerful story and why?',
    'Welches geheimnisvolle Detail entdeckt man erst beim zweiten Hinsehen?':
      'Which mysterious detail is only discovered upon closer inspection?',
    'Wenig hilft oft mehr: Nur ein bis zwei Tropfen Farbe nehmen, sonst schmeckt der Trank komisch.':
      'Less is often more: Use only one or two drops of color, otherwise the potion will taste strange.',
    'Wenig Kleber genügt; zu viel macht die Watte flach.':
      'A little glue is enough; too much will flatten the cotton wool.',
    'Weniger gruselig': 'Less creepy',
    'Weniger Spinat und etwas mehr Mango verwenden.': 'Use less spinach and a little more mango.',
    'Weniger süss': 'Less sweet',
    'Wenn das Timing schwerfällt: den Gegenstand stattdessen an einem dünnen, später wegretuschierbaren Faden aufhängen und von der Seite fotografieren.':
      'If timing is difficult: instead, hang the object from a thin thread that can be retouched later and photograph it from the side.',
    'Wenn der Karton beim Schneiden verrutscht, bitte eine erwachsene Person zum Festhalten dazuholen.':
      'If the cardboard slips while cutting, please get an adult to hold it.',
    'Wenn die Augen unten verschwinden, kurz mit einem langen Löffel anheben.':
      'If the eyes disappear at the bottom, briefly lift them with a long spoon.',
    'Wenn die Farbe noch klebt: einfach noch etwas länger warten, nicht anfassen.':
      "If the paint is still sticky: simply wait a little longer and don't touch it.",
    'Wenn ihr euch nicht einigen könnt, wer gewinnt: Beide Tränke bekommen einen eigenen Titel statt nur einen Gewinner.':
      "If you can't agree on who wins: both potions get their own title instead of just one winner.",
    'Wenn ihr feststeckt, darf jede genau einen kleinen Hinweis geben.':
      'If you get stuck, each of you can give exactly one small clue.',
    'Wenn sich die Farben zu schnell vermischen: Trank kurz ruhen lassen, dann vorsichtig einen weiteren Tropfen Sirup ganz langsam am Rand hinzufügen.':
      'If the colors mix too quickly: Let the drink rest briefly, then carefully add another drop of syrup very slowly at the edge.',
    'Wenn sich nach ein paar Minuten nichts tut: Papierstreifen prüfen - beide Enden müssen wirklich im Wasser bzw. am Glasrand fest anliegen.':
      'If nothing happens after a few minutes: Check the paper strip – both ends must be firmly in contact with the water or the rim of the glass.',
    'Wenn zwei Farben verschmelzen, ist das eine neue Regenbogenfarbe – nicht gescheitert.':
      "If two colors merge, it's a new rainbow color – you haven't failed.",
    'Wer forscht gerade?': 'Who is currently investigating?',
    'Wer hat die geheimen Spuren im Moor hinterlassen?': 'Who left the secret tracks in the swamp?',
    'Wickle die Figur locker ein und lege eine Fluch-Botschaft dazu.':
      'Wrap the figure loosely and include a curse message.',
    'Wie gelangt gefärbtes Wasser bis in die Blätter?':
      'How does colored water get into the leaves?',
    'Wie hieß dein Sumpfmonster und konnte man den Spinat schmecken?':
      'What was the name of your swamp monster, and could you taste the spinach?',
    'Wie hiess dein Vampir und wie sah sein Smoothie aus?':
      "What was your vampire's name and what did their smoothie look like?",
    'Wie hoch war die pinke Wolke über deinem Drink?':
      'How high was the pink cloud above your drink?',
    'Wie lange blieb dein Blutmond gefroren?': 'How long did your blood moon stay frozen?',
    'Wie laut haben deine Drachenfunken geknistert?': 'How loud did your dragon sparks crackle?',
    'Wie sah dein Kakao-Geist aus und welchen Namen hatte er?':
      'What did your cocoa ghost look like and what was their name?',
    'Wie sieht deine Geisterfigur in ihrem neuen Bett aus? Was macht das Bett besonders gruselig?':
      'What does your ghost figure look like in their new bed? What makes the bed especially creepy?',
    'Wie sollen wir dich nennen?': 'What should we call you?',
    'Wie stark hat dein Elixier geleuchtet und wie sauer war der Zauberblitz?':
      'How bright was your elixir and how sour was the magic lightning bolt?',
    'Wie verändert sich ein Schatten im Verlauf eines Tages?':
      'How does a shadow change over the course of a day?',
    'Wie verändert Spülmittel die Verteilung auf der Wasseroberfläche?':
      "How does dish soap change the distribution on the water's surface?",
    'Wie viel ist da?': 'How much is there?',
    'Wie viele Farbtropfen hält die Schaumwolke, bevor es darunter regnet?':
      'How many drops of color does the foam cloud hold before it rains underneath?',
    'Wie viele Mondschichten konntest du erkennen?': 'How many moon layers could you see?',
    'Wie viele Monsteraugen waren in deinem Glas?': 'How many monster eyes were in your glass?',
    'Wie war die Schwierigkeit?': 'How difficult was it?',
