    'Zeit abgelaufen! ⏰': "Time's up! ⏰",
    'Ziehe mit einem Löffel zwei langsame Kreise, sodass Nebelwirbel sichtbar bleiben.':
      'Draw two slow circles with a spoon so that the mist swirls remain visible.',
