    'Baue und fotografiere eine kleine Tür an einem unerwarteten Ort.':
      'Construye y fotografía una puerta pequeña en un lugar inesperado.',
    'Baut abwechselnd einen hohen Turm, ohne über den nächsten Schritt zu sprechen.':
      'Túrnense para construir una torre alta sin hablar del siguiente paso.',
    'Baut getrennt zwei Hälften, die am Ende zusammenpassen müssen.':
      'Construye dos mitades por separado que deben encajar al final.',
    'Bedecke den Deckel stellenweise mit gezupfter Watte.':
      'Cubre la tapa en algunas partes con algodón.',
    'Befestige zuerst vier lange Hauptfäden und verbinde sie danach mit kurzen Fäden.':
      'Primero, coloca cuatro hilos principales largos y luego conéctalos con hilos cortos.',
    'Befeuchte den Glasrand mit wenig Zitronensaft und drücke ihn vorsichtig in die Mischung.':
      'Humedece el borde del vaso con un poco de jugo de limón y presiónalo suavemente sobre la mezcla.',
    Behälter: 'Contenedor',
    'Bei Milchallergie oder Unverträglichkeit einen passenden Pflanzendrink verwenden.':
      'Si tienes alergia o intolerancia a la leche, usa una alternativa vegetal adecuada.',
    'Bei welchem Abstand sieht dein Schattenmonster am wildesten aus?':
      '¿A qué distancia se ve más salvaje tu monstruo de sombra?',
    'Beides kann jederzeit geändert werden. Crazy Lab respektiert zusätzlich die iPhone-Einstellung „Bewegung reduzieren“.':
      'Ambos valores se pueden cambiar en cualquier momento. Crazy Lab también respeta la configuración de "Reducir movimiento" del iPhone.',
    'Beim Reiben werden elektrische Ladungen getrennt. Der geladene Ballon zieht nahe leichte Gegenstände an.':
      'Frotar separa las cargas eléctricas. El globo cargado atrae los objetos ligeros cercanos.',
    'Beim Zuschneiden von Karton auf die Fingerhaltung achten.':
      'Presta atención a la posición de tus dedos al cortar cartón.',
    'Bemale das Bettgestell schwarz-violett und lass es kurz trocknen.':
      'Pinta el marco de la cama de negro y morado y déjalo secar brevemente.',
    'Bemale Deckel als Trankflaschen und Papier als Forschungshefte.':
      'Pinta tapas para usarlas como frascos de pociones y papel como cuadernos de investigación.',
    'Beobachte die aufsteigenden Schleimblasen und probiere den Fizz.':
      'Observa las burbujas de limo que suben y prueba la efervescencia.',
    'Beobachte, wie der gefrorene Mond aufbricht.': 'Observa cómo se abre la luna congelada.',
    'Beobachte, wie Farbgeister von Glas zu Glas wandern - ein echtes Kapillar-Experiment.':
      'Observa cómo fantasmas de colores viajan de vaso en vaso: un verdadero experimento capilar.',
    'Beobachte, wie gemahlene Kräuter auf Wasser davonhuschen.':
      'Observa cómo las hierbas molidas flotan en el agua.',
    'Bereitet gemeinsam das Grundrezept vor: je 150 ml Zitronenlimonade und 50 ml Traubensaft pro Glas.':
      'Preparen juntos la receta básica: 150 ml de limonada y 50 ml de jugo de uva por vaso.',
    'Beschreibe genau, was du siehst, ohne gleich eine Erklärung zu erfinden.':
      'Describe con exactitud lo que ves sin inventar una explicación.',
    'Bestreue den Trank optional mit essbarem Glitzer und hänge den Fruchtgummi-Wurm an den Glasrand.':
      'Opcionalmente, espolvorea la poción con brillantina comestible y cuelga el gusano de goma en el borde del vaso.',
    'Betrachte zuerst die Mondschichten und verrühre sie erst vor dem Trinken.':
      'Primero, observa las capas de la luna y mézclalas justo antes de beber.',
