    'Wenig hilft oft mehr: Nur ein bis zwei Tropfen Farbe nehmen, sonst schmeckt der Trank komisch.':
      'Menos es más: usa solo una o dos gotas de color, de lo contrario la poción tendrá un sabor extraño.',
